	'messages:config-admin-password' => 'ast:Contraseña:',
	'messages:config-admin-password-confirm' => 'ast:Repiti la contraseña:',
	'messages:config-admin-help' => 'ast:Escribe equí\'l nome d\'usuariu que desees, como por casu "Nel Bloggs".
